// The canon home repo's OWN local pack — Claudinite-specific working rules and
// lessons that are NOT portable to consumers (those belong in packs/, the shared
// canon). This is the capture surface the growth-extract scheduled task routes the
// canon's own non-portable lessons into — from repo activity and from captured
// conversations alike; a lesson that turns out to travel becomes a PR against
// packs/ instead.
//
// Discovered like any local pack — the canon's own runner passes
// discoverPacks({ localRoot: <repo root> }), so this is scanned alongside the
// canon packs/ tree — and active because .claudinite-settings.json declares it. Its
// id must equal its directory name ("claudinite") and may not shadow a canon pack.
export default {
  ruleRoutingGuidance: {
    belongs: 'developing Claudinite itself — its scope and standing decisions, the engine, the mount, the queue and what reaches members',
    excludes: 'the packs on the shelf — naming, config, modules, checks, prose, versions — and fleet-facing curation: claudinite-canon-curation',
  },
  // home-seeded-packs-declared rides beside these as a declared check
  // (declared-checks.json in this directory).
};

[
  {
    "id": "home-seeded-packs-declared",
    "severity": "blocking",
    "failureMessage": "baselining lands a seeded pack on every member but is gated !isHome, so a newly seeded pack reaches the whole fleet except this repo, invisibly",
    "scanIgnoringComments": true,
    "requireIndexCoverage": [
      {
        "eachTrackedPathMatching": "/^packs\\/(?<pack>[^/]+)\\/pack\\.mjs$/",
        "whoseTextMatches": "/(^|[^\\w.$])seededByDefault\\s*:\\s*true\\b/",
        "indexFile": ".claudinite-settings.json",
        "coveredByValueInArrayAtField": {
          "atField": "packs",
          "value": "{pack}",
          "matchingEntryObjectsByField": "id"
        },
        "whenIndexFileAbsent": "assertNothing",
        "anchorFindingsAt": "indexFile",
        "what": "the \"{pack}\" pack flags seededByDefault (packs/{pack}/pack.mjs) but is not declared here",
        "fix": "add \"{pack}\" to the \"packs\" array — baselining skips the home, so this repo's declaration is hand-maintained; a deliberate opt-out is an acceptance with a reason instead"
      }
    ]
  },
  {
    "id": "legacy-tolerance-scheduled",
    "severity": "blocking",
    "since": "2026-09-03",
    "failureMessage": "a legacy tolerance nobody is scheduled to remove is a permanent feature wearing a temporary name, and its holders are never told to move off it",
    "scanFiles": "/^(engine|packs)\\/.*\\.mjs$/",
    "excludeFileClasses": [
      "testFiles"
    ],
    "matchLines": [
      {
        "match": "/^(?:export\\s+)?(?:const|let|function|async function)\\s+\\w*(?:LEGACY|Legacy)\\w*/",
        "unlessPreviousLineMatches": "/@legacy-tolerance/",
        "what": "{match} declares a legacy tolerance with no scheduled removal above it",
        "fix": "put `// @legacy-tolerance advisory:<rule-id|none> retire:#<issue>` directly above it: the rule that tells a holder to migrate, and the issue whose merge deletes this code"
      },
      {
        "match": "/@legacy-tolerance/",
        "unlessLineMatches": "/@legacy-tolerance advisory:(?:[a-z][a-z0-9/-]*) retire:#\\d+$/",
        "what": "{match} is not a readable tolerance annotation",
        "fix": "write it as `// @legacy-tolerance advisory:<rule-id|none> retire:#<issue>` with nothing after — a grep for this token is the register, and an unparseable form is not in it"
